function stars(){const pole=eq2ecl(192.85948,27.12825),gc=eq2ecl(266.405,-28.936),z=new THREE.Vector3(...pole).normalize(),x0=new THREE.Vector3(...gc),x=x0.sub(z.clone().multiplyScalar(x0.dot(z))).normalize(),y=new THREE.Vector3().crossVectors(z,x);
const mk=(n,sz,bright)=>{const pos=[],col=[];for(let i=0;i<n;i++){let l,b;if(Math.random()<0.62){const g=()=>Math.random()+Math.random()+Math.random()-1.5;b=g()*7*D;l=(Math.random()<0.4?g()*60*D:Math.random()*2*Math.PI)}else{l=Math.random()*2*Math.PI;b=Math.asin(2*Math.random()-1)}
const v=x.clone().multiplyScalar(Math.cos(b)*Math.cos(l)).add(y.clone().multiplyScalar(Math.cos(b)*Math.sin(l))).add(z.clone().multiplyScalar(Math.sin(b))).multiplyScalar(9e5);pos.push(v.x,v.z,-v.y);
const t=Math.random(),k=bright*(0.35+0.65*Math.random()**2);col.push(k*(t<0.2?0.7:t<0.8?1:1),k*(t<0.2?0.8:t<0.8?0.97:0.85),k*(t<0.2?1:t<0.8?0.92:0.65))}
const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
const p=new THREE.Points(g,new THREE.PointsMaterial({size:sz,sizeAttenuation:false,vertexColors:true,depthWrite:false}));p.frustumCulled=false;scene.add(p);return p};
return[mk(9000,1,0.8),mk(700,2,1)]}
